using System.Collections.Concurrent;
using System.Text;
using System.Text.Json.Nodes;

namespace ScriptWidget.Core.Runtime;

/// <summary>JavaScript assets generated by <c>Windows/scripts/build-shared-js.mjs</c>.</summary>
public sealed class SharedScripts
{
    private readonly string directory;
    private readonly ConcurrentDictionary<string, string> cache = new();
    private readonly Lazy<IReadOnlyList<string>> hostFiles;
    private readonly Lazy<JsonObject> contractFile;

    /// <param name="directory">Folder with kernel.js and the other assets; defaults to <c>assets/scriptwidget</c> next to the program.</param>
    public SharedScripts(string? directory = null)
    {
        this.directory = directory ?? Path.Combine(AppContext.BaseDirectory, "assets", "scriptwidget");
        if (!File.Exists(Path.Combine(this.directory, "kernel.js"))) throw new FileNotFoundException("ScriptWidget runtime assets are missing. Run node Windows/scripts/build-shared-js.mjs.", Path.Combine(this.directory, "kernel.js"));
        // host.js defines the registry the API files add themselves to.
        hostFiles = new(() => new[] { "host.js" }.Concat(Directory.EnumerateFiles(this.directory, "apis-*.js").Select(Path.GetFileName).OfType<string>().Order(StringComparer.Ordinal)).ToList());
        contractFile = new(() => Json.ParseObject(Text("contract.json")));
    }

    public string Text(string name) => cache.GetOrAdd(name, file => File.ReadAllText(Path.Combine(directory, file), Encoding.UTF8));

    /// <summary>Host files evaluated before the kernel, in order.</summary>
    public IReadOnlyList<string> HostFiles => hostFiles.Value;

    public JsonObject Contract => (JsonObject)contractFile.Value["contract"]!;
    public JsonObject ErrorCategories => (JsonObject)contractFile.Value["errorCategories"]!;

    public string? SupportScript(string name) => name is "util.js" or "moment.min.js" ? Text(name) : null;
}
